const page = $input.first().json;
const matches = (page.candidates || []).map((candidate) => {
  const rules = candidate.segment_rules || {};
  const missing = [];
  const minimumIncome = rules.minimum_monthly_income_inr;
  if (rules.salary_account_required) {
    missing.push('Confirm you have the required lender salary account');
    missing.push('The lender does not publish a numeric credit-score cutoff; confirm its internal policy');
  }
  const thresholds = rules.income_thresholds_by_sector_inr;
  if (thresholds && typeof thresholds === 'object') {
    const labels = Object.entries(thresholds).map(([key, amount]) => {
      const normalized = key.toLowerCase();
      const label = normalized.includes('government') || normalized.includes('defence') ? 'Government/Defence' : normalized.includes('corporate') ? 'Corporate' : key.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
      return `${label}: INR ${Number(amount).toLocaleString('en-IN')} net monthly salary`;
    }).join(', ');
    const serviceMonths = Array.isArray(rules.minimum_service_months_by_sector) ? rules.minimum_service_months_by_sector : [];
    const serviceNote = serviceMonths.length ? ` Minimum service is ${serviceMonths[0]} months for Government/Defence and ${serviceMonths[serviceMonths.length - 1]} months for Corporate applicants.` : '';
    missing.push(`Confirm your sector and applicable threshold (${labels}).${serviceNote} The CSV does not identify sector or whether income is net salary.`);
  }
  if (rules.total_work_experience_years) {
    missing.push(candidate.lender === 'HDFC Bank' ? 'Confirm an eligible employer, at least 2 years of total work experience, and at least 1 year with the current employer' : "Confirm the lender's required work experience");
  }
  const reasons = ['Potential fit against available published criteria; this is not lender approval.'];
  if (minimumIncome !== null && minimumIncome !== undefined) {
    const amount = Number(minimumIncome).toLocaleString('en-IN');
    reasons.push(candidate.lender === 'HDFC Bank' ? `Reported monthly income is at or above INR ${amount}; HDFC specifies net monthly income, which this file does not distinguish from gross income.` : `Monthly income meets the published minimum of INR ${amount}.`);
  }
  if (rules.credit_score_preferred) reasons.push(`A credit score of ${rules.credit_score_preferred} or above is preferred, not a hard minimum.`);
  reasons.push(...missing);
  return { applicant_id: candidate.applicant_id, product_id: candidate.product_id, criteria_version: candidate.criteria_version, match_status: missing.length ? 'needs_information' : 'potential', reasons };
});
return [{ json: { job_id: page.job_id, batch_id: page.batch_id, criteria_fingerprint: page.criteria_fingerprint, applicants_checked: page.applicants_checked, verified_products_checked: page.verified_products_checked, matches, idempotent_replay: page.idempotent_replay === true } }];
